const e=/^(cmp:|path:|tag:)/;var o={tag:"console",dependencies:["./ok-console-service.ok.js"],context:o=>({query:"",collapsed:new WeakSet,activeTag:null,verbose:!1,get logs(){const e=o.$ok.shared.console.logs;if(this.activeTag)return e.filter(e=>e.tags.includes(this.activeTag));if(!this.query)return e;const t=this.query.toLowerCase();return e.filter(e=>e.tags.some(e=>e.toLowerCase().includes(t))||JSON.stringify(e.data).toLowerCase().includes(t))},get allTags(){const t=new Set;for(const a of o.$ok.shared.console.logs)for(const o of a.tags)!this.verbose&&e.test(o)||t.add(o);return[...t].sort()},visibleTags(o){return this.verbose?o.tags:o.tags.filter(o=>!e.test(o))},toggle(e){this.collapsed.has(e)?this.collapsed.delete(e):this.collapsed.add(e)},isCollapsed(e){return this.collapsed.has(e)},clear(){o.$ok.shared.console.clear()},remove(e){o.$ok.shared.console.remove(e)},filterBy(e){this.activeTag=this.activeTag===e?null:e,this.query=""}}),mounted(e){const o=new MutationObserver(()=>{const o=e.$el.querySelector(".logs");o.scrollTop=o.scrollHeight});e.$ext("unmount",()=>o.disconnect())},template:'<div class="toolbar"><input type="text" :bind="query" placeholder="Search logs..."><label class="verbose-toggle" title="Show internal tags (component ids, paths)"><input type="checkbox" :checked="verbose" @input="verbose = $el.checked">internal</label> <button @click="clear">Clear</button></div><div class="tags"><each :="allTags" let:item="tag"><button class="tag-btn" :class="{ active: activeTag === tag }" @click="filterBy(tag)">{{ tag }}</button></each></div><div class="logs"><virtualized :="logs" pin="bottom" let:item="log"><div class="log" :class="[ log.tags.includes(\'error\') && \'error\', log.tags.includes(\'warn\') && \'warn\', log.tags.includes(\'info\') && \'info\', log.tags.includes(\'verbose\') && \'verbose\', isCollapsed(log) && \'collapsed\' ]"><div class="header" @click="toggle(log)"><span class="tags"><each :="visibleTags(log)" let:item="tag"><span class="tag">{{ tag }}</span></each></span><span class="time">{{ new Date(log.timestamp).toLocaleTimeString() }}</span> <button class="remove" @click="remove(log)">✕</button></div><if :="log.data instanceof Error"><ok-crash-info no-close :error="log.data" style="max-height:100%"/><else><pre class="data">{{ JSON.stringify(log.data, null, 2) }}</pre></else></if></div></virtualized></div>',style:"[tag]{display:flex;flex-direction:column;flex:1;min-height:0;min-width:0;font-family:monospace;font-size:12px}.toolbar,.verbose-toggle{display:flex;align-items:center}.toolbar{gap:6px;padding:4px;background:rgba(128,128,128,.08);border-bottom:var(--ok_border-muted, 1px solid rgba(128,128,128,0.25));flex:none}.toolbar button,.toolbar input[type=text]{background:0 0;color:inherit;box-shadow:none;border:var(--ok_border-muted, 1px solid rgba(128,128,128,0.35));border-radius:4px;font:inherit}.toolbar input[type=text]{flex:1;padding:2px 6px}.verbose-toggle{gap:4px;opacity:.7;white-space:nowrap;cursor:pointer}.toolbar button{padding:2px 10px;cursor:pointer}.toolbar button:hover{background:rgba(128,128,128,.15);box-shadow:none}.tags{display:flex;flex-wrap:wrap;gap:4px;padding:4px;flex:none}.tags:empty{display:none}.tag-btn{padding:1px 6px;border:0;box-shadow:none;background:rgba(128,128,128,.18);color:inherit;cursor:pointer;border-radius:4px;font-size:.85em;opacity:.85}.tag-btn.active{background:var(--ok_fg-accent, #09f);color:#fff;opacity:1}.logs{flex:1;overflow:auto}.log{border-bottom:1px solid rgba(128,128,128,.15)}.log .header{display:flex;justify-content:space-between;align-items:center;padding:3px 4px;cursor:pointer}.log .header:hover{background:rgba(128,128,128,.08)}.log.collapsed .data{display:none}.log .tags{display:flex;gap:6px;flex-wrap:wrap;padding:0}.log .tag{background:rgba(128,128,128,.18);padding:1px 6px;border-radius:4px;font-size:.85em}.log .time{font-size:.75em;opacity:.55;margin-left:auto;margin-right:8px}.log .remove{background:0 0;border:0;box-shadow:none;color:inherit;opacity:.5;font-size:1em;cursor:pointer}.log .remove:hover{opacity:1}.log .data{padding:4px 8px;white-space:pre-wrap;word-break:break-word;opacity:.9}.log.info .tag{background:color-mix(in srgb,#3af 20%,transparent)}.log.warn .tag{background:color-mix(in srgb,#fc2 25%,transparent)}.log.error .tag{background:color-mix(in srgb,#f45 25%,transparent)}.log.error .header{box-shadow:inset 2px 0 0#f45}.log.warn .header{box-shadow:inset 2px 0 0#fc2}.log.verbose .tag{opacity:.6}"};export{o as default};
